// Wave 11, Thailand 2/3: Ayutthaya & Kanchanaburi, Hua Hin (with Cha-am, Pranburi, Sam Roi Yot and Phetchaburi) — temples only as
// buildings and ruins, never a Buddha image; the Kanchanaburi railway only as a little train on its wooden trestle (no war imagery).
import { P, R, C, E, Lc, g, face, free, scene, cityStamp, INK } from '../lib.mjs';

const nm = (th, en) => ({ th, en });
