const gable = (cx, y, w, h, fill = '#D84315', edge = '#2E7D32') => P(`M${cx - w / 2} ${y + h}L${cx} ${y}L${cx + w / 2} ${y + h}z`, fill) + Lc(`M${cx - w / 2 + 4} ${y + h - 3}L${cx} ${y + 4}L${cx + w / 2 - 4} ${y + h - 3}`, edge, 3) + Lc(`M${cx} ${y}c-1-8 6-12 10-8`, GOLD, 3.5) + Lc(`M${cx - w / 2} ${y + h}c-6 0-8-6-4-9M${cx + w / 2} ${y + h}c6 0 8-6 4-9`, GOLD, 3);
// a brick prang (corn-cob tower) of height h, standing on y
const prang = (x, y, w, h, c = BRICK) => P(`M${x - w / 2} ${y}l${w * 0.1}-${h * 0.35}h${w * 0.8}l${w * 0.1} ${h * 0.35}z`, c) + P(`M${x - w * 0.36} ${y - h * 0.35}c0-${h * 0.35} ${w * 0.16}-${h * 0.55} ${w * 0.36}-${h * 0.65} ${w * 0.2} ${h * 0.1} ${w * 0.36} ${h * 0.3} ${w * 0.36} ${h * 0.65}z`, c)
  + Lc(`M${x - w * 0.3} ${y - h * 0.5}h${w * 0.6}M${x - w * 0.22} ${y - h * 0.68}h${w * 0.44}`, '#8D3B22', 2);
// a bell-shaped chedi of height h on y
const bell = (x, y, w, h, c = '#B0BEC5') => R(x - w / 2, y - h * 0.18, w, h * 0.18, c) + P(`M${x - w * 0.38} ${y - h * 0.18}c0-${h * 0.3} ${w * 0.14}-${h * 0.42} ${w * 0.38}-${h * 0.42}s${w * 0.38} ${h * 0.12} ${w * 0.38} ${h * 0.42}z`, c) + P(`M${x - w * 0.1} ${y - h * 0.6}l${w * 0.1}-${h * 0.4} ${w * 0.1} ${h * 0.4}z`, c);
